import{z as n,x as B,o as e,c as p,q as r,j as o,D as E,d as t,s as i,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"抽样计划","description":"","frontmatter":{"title":"抽样计划","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/sampling-plan.md","filePath":"litho/sampling-plan.md","lastUpdated":1791413859000}'),d={name:"litho/sampling-plan.md"};function h(C,a,m,P,D,c){const l=B("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="抽样计划" tabindex="-1">抽样计划 <a class="header-anchor" href="#抽样计划" aria-label="Permalink to &quot;抽样计划&quot;">​</a></h1><div class="epigraph"><p>抽哪些场、哪些片、哪些垫，决定 APC 看见哪张指纹、SPC 看见哪类漂移；没抽到的空间频率在控制里等于不存在。</p><footer>—— 对照半导体计量抽样与 SEMI 对计量策略的通称；套刻高阶拟合对采样密度的公开要求</footer></div><p><a href="/litho/feedforward-feedback-r2r">上一课</a>要前馈与反馈。缺口是可观测性：每批量 2 片 × 9 点，看不见边场弓形，高阶校正会去拟合噪声。本课钉抽样计划。控制图如何用这些点判决，留给<a href="/litho/spc-control-chart">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计量产能有限：CD-SEM 慢，套刻较快仍不是每场全垫。抽样是空间（场内、场间、晶圆半径）、时间（每片/每批/每 N 批）和产品（哪些层全检）的合同。欠采样：指纹混入残差，APC 补错项，边场良率死。过采样：扫描机等计量，WIP 堆积，或用过时数据补未来批次。</p><p><span class="marginnote">术语翻译：APC（先进过程控制）是「用测量结果自动回头修机台配方」的反馈系统；SPC（统计过程控制）是「画控制图盯漂移」的报警系统。两者都只能看见抽样计划喂给它们的那些点——没抽的点，它们就当不存在。</span></p><p>缺口是<strong>与模型阶次匹配的采样</strong>，不是「越多越好」。<a href="/litho/high-order-overlay">高阶套刻</a> 已说项一开就需要密读数；本课把这句话写成计划：开哪些项，就必须有哪些点。</p><h3 id="产品图形对专用垫" tabindex="-1">产品图形对专用垫 <a class="header-anchor" href="#产品图形对专用垫" aria-label="Permalink to &quot;产品图形对专用垫&quot;">​</a></h3><p>套刻垫和 CD 垫不代表 SRAM 拐角。抽样若只在划片道，APC 会把器件偏置当不存在。关键层应对产品内或专用阵列抽样，与对准树一致。PWQ 是鉴定抽样，不能替代量产抽样。</p><p><span class="marginnote">边缘场与部分场（后课）若从不进样本，边缘良率问题会在客户失效里首次出现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：对目标指纹的空间频率做 Nyquist 式估计（工程上：场内点数 ≥ 校正项自由度的数倍）。分层：监控用稀疏，触发后加密，异常批全检。与缺陷检测抽样不同：缺陷是稀疏事件，CD/套刻是连续场——计划不要混用同一张图。动态抽样：APC 残差或 SPC 告警后加测，属同一合同。</p><p>计划要写进层食谱：默认点、加密点、禁止永远跳过的边缘场。ASML 对高阶 overlay 的公开要求，本质上就是「开项必须有点」；本课把这句话从套刻推广到 CD 地图。</p><p><span class="marginnote">直觉类比：想知道一条正弦波长什么样，每个周期至少要采两个点；想看见「边场弓形」这种慢弯曲，点就得铺到弓形的两端和中间。点全挤在场心，等于只看了波的一个相位。</span></p>',14)),(e(),o(s,null,{default:E(()=>[i(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20BASE%5B%22%E9%BB%98%E8%AE%A4%E7%A8%80%E7%96%8F%E7%9B%91%E6%8E%A7%E7%82%B9%22%5D%20--%3E%20WATCH%5B%22SPC%20%2F%20APC%20%E6%AE%8B%E5%B7%AE%E7%9B%91%E8%A7%86%22%5D%0A%20%20WATCH%20--%3E%7C%22%E5%91%8A%E8%AD%A6%22%7C%20DENSE%5B%22%E8%A7%A6%E5%8F%91%E5%8A%A0%E5%AF%86%E5%8A%A0%E6%B5%8B%22%5D%0A%20%20DENSE%20--%3E%7C%22%E4%BB%8D%E8%B6%85%E9%99%90%22%7C%20FULL%5B%22%E5%BC%82%E5%B8%B8%E6%89%B9%E5%85%A8%E6%A3%80%22%5D%0A%20%20FULL%20--%3E%7C%22%E6%81%A2%E5%A4%8D%E6%AD%A3%E5%B8%B8%22%7C%20BASE%0A%20%20EDGE%5B%22%E8%BE%B9%E7%BC%98%E5%9C%BA%3A%20%E7%A6%81%E6%AD%A2%E6%B0%B8%E8%BF%9C%E8%B7%B3%E8%BF%87%22%5D%20--%3E%20BASE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"校正模型是多项式或扫描仪项，参数估计的方差随点数与布局走。点都在场心，高阶项不可辨识，估计器会把噪声当弓形。时间上，批内第一片代表不了热漂移后的稳态——扫描机热课已有；抽样应含热态片。偏差：永远抽同一 slot 会与轨道某一涂胶路径混杂。",-1)),(e(),o(s,null,{default:E(()=>[i(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E8%A6%81%E6%8E%A7%E7%9A%84%E6%8C%87%E7%BA%B9%E9%98%B6%E6%AC%A1%22%5D%20--%3E%20N%5B%22%E5%9C%BA%E5%86%85%20%2F%20%E5%9C%BA%E9%97%B4%E7%82%B9%E6%95%B0%22%5D%0A%20%20N%20--%3E%20PLAN%5B%22%E6%8A%BD%E6%A0%B7%E8%AE%A1%E5%88%92%22%5D%0A%20%20WIP%5B%22%E8%AE%A1%E9%87%8F%E4%BA%A7%E8%83%BD%22%5D%20--%3E%20PLAN%0A%20%20PLAN%20--%3E%20APC%5B%22%E5%8F%AF%E8%BE%A8%E8%AF%86%E7%9A%84%20APC%20%E9%A1%B9%22%5D%0A%20%20MISS%5B%22%E6%9C%AA%E9%87%87%E6%A0%B7%E9%A2%91%E7%8E%87%22%5D%20--%3E%20BLIND%5B%22%E7%9B%B2%E5%8C%BA%E8%89%AF%E7%8E%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>未采样的空间频率在控制里等于不存在。边缘场若从不进样本，高阶项在刀口无约束，器件却在那里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某厂的「每批 4 片」写成标准。不重写 CD-SEM 算法。缺陷检测的抽样在良率课另写。</p><p>后课默认：抽样阶次 ≥ 控制阶次。下一课 SPC 用这些点画图，但不创造未测到的信息。</p><p><span class="marginnote">常见误区：以为「抽样越多越好」。过采样不是免费的保险——扫描机在等计量、WIP 堆积，等数据回来机台状态早变了，拿旧数据补新批次反而补错。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>抽样必须覆盖要补偿的空间频率与热态。</li><li>划片垫不自动代表产品图形。</li><li>动态加密是计划的一部分，不是临时救火。</li><li>出处：计量抽样与高阶套刻采样公开要求；SEMI 计量策略通称。</li></ul>',7))])}const u=n(d,[["render",h]]);export{S as __pageData,u as default};
